options.customCss:
:root{--hc-bg:#faf5ef;--hc-surface:#ffffff;--hc-tint:#fdf8f2;--hc-line:#efe4d6;--hc-txt:#2a1d14;--hc-muted:#8a7869;--hc-accent:#e0821f;--hc-accent-soft:#fdf1e2}
body{background:radial-gradient(900px 500px at 85% -10%,#fdece0 0%,transparent 60%),radial-gradient(700px 420px at -10% 110%,#f8ebe2 0%,transparent 55%),var(--hc-bg) !important;color:var(--hc-txt) !important}
.card{background:var(--hc-surface) !important;border:1px solid var(--hc-line) !important;border-left:4px solid var(--hc-accent) !important;border-radius:14px !important;box-shadow:0 6px 20px rgba(120,80,40,.08) !important}
.form-header h1{color:var(--hc-txt) !important;font-weight:700 !important}
.form-header p{color:var(--hc-muted) !important}
.form-label,label{color:var(--hc-txt) !important;font-weight:600 !important}
.form-input,.select-input,input,select,textarea{background:var(--hc-tint) !important;border:1px solid var(--hc-line) !important;color:var(--hc-txt) !important;border-radius:10px !important}
.form-input:focus,.select-input:focus,input:focus,select:focus,textarea:focus{border-color:var(--hc-accent) !important;outline:none !important;box-shadow:0 0 0 3px rgba(224,130,31,.15) !important}
.form-input::placeholder,input::placeholder{color:var(--hc-muted) !important;opacity:.8}
#submit-btn{background:var(--hc-accent) !important;border:none !important;color:#fff !important;font-weight:700 !important;border-radius:10px !important;box-shadow:0 4px 12px rgba(224,130,31,.25) !important}
#submit-btn:hover{filter:brightness(1.06)}
.n8n-link,.n8n-link a,.n8n-link p{color:var(--hc-muted) !important}
#submitted-header{color:var(--hc-txt) !important}
#submitted-content{color:var(--hc-muted) !important}
.form-group.html a{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:10px;background:var(--hc-surface);border:1px solid var(--hc-line);color:var(--hc-accent) !important;text-decoration:none !important;font-size:14px;font-weight:600;box-shadow:0 2px 6px rgba(120,80,40,.06)}
.form-group.html a:hover{border-color:var(--hc-accent);background:var(--hc-accent-soft)}

